+/** A ticket's scope: a full (weekly) reset, or a reset for one model only. */
+export type TicketScope = {
+	scope?: string | null;
+	model?: string | null;
+};
+
+/** Short kind of a ticket: the model name, or `Full` for a full reset. */
+export function ticketKind(ticket: TicketScope = {}): string {
+	return ticket.scope === "model" ? (ticket.model ?? "Model") : "Full";
+}
+
+/** `Fable reset` for a model ticket, `Full reset` otherwise (incl. pre-model caches). */
+export function ticketName(ticket: TicketScope = {}): string {
+	return `${ticketKind(ticket)} reset`;
+}
+
+/** What spending the ticket does, for the card's ticket row. */
+export function ticketEffect(ticket: TicketScope = {}): string {
+	if (ticket.scope === "model") return `Resets the ${ticket.model ?? "model"} allowance`;
+	return "Resets weekly usage now";
+}
+
+/** Live tickets soonest-first: lapsed ones (and ones without an expiry) are dropped. */
+export function liveTickets<T extends TicketScope & { expiresAt: number }>(tickets: readonly T[], now = Date.now()): T[] {
+	return tickets
+		.filter((ticket) => {
+			const ms = resetAtMs(ticket.expiresAt);
+			return ms != null && ms > now;
+		})
+		.toSorted((a, b) => (resetAtMs(a.expiresAt) ?? 0) - (resetAtMs(b.expiresAt) ?? 0));
+}
+
+/** The soonest live ticket that clears weekly usage; model tickets never drive the weekly chart. */
+export function weeklyTicket<T extends TicketScope & { expiresAt: number }>(
+	tickets: readonly T[],
+	now = Date.now(),
+): T | undefined {
+	return liveTickets(tickets, now).find((ticket) => ticket.scope !== "model");
+}
